:root { --color-white: #ffffff; --color-text: #f8f6f0; --color-page-text: #f7f5ef; --color-surface-dark: #111112; --text-1: rgba(248, 246, 240, 0.96); --text-2: rgba(248, 246, 240, 0.68); --text-3: rgba(248, 246, 240, 0.54); --font-ui: "Segoe UI Variable Text", "Segoe UI", "Microsoft YaHei UI", "Microsoft YaHei", system-ui, sans-serif; --color-white-a04: rgba(255, 255, 255, 0.04); --color-white-a06: rgba(255, 255, 255, 0.06); --color-white-a08: rgba(255, 255, 255, 0.08); --color-white-a10: rgba(255, 255, 255, 0.1); --color-white-a12: rgba(255, 255, 255, 0.12); --color-white-a16: rgba(255, 255, 255, 0.16); --color-accent: #74d6ff; --color-on-accent: #06202c; --color-focus-ring: rgba(143, 216, 255, 0.88); --radius-sm: 6px; --radius-md: 8px; --radius-lg: 10px; --radius-xl: 12px; --motion-ease: cubic-bezier(0.2, 0.8, 0.2, 1); --motion-ease-out: cubic-bezier(0.22, 1, 0.36, 1); --motion-fast: 120ms; --motion-medium: 240ms; }
.island-light { --color-text: #18181e; --color-page-text: #18181e; --text-1: rgba(24, 24, 30, 0.94); --text-2: rgba(24, 24, 30, 0.7); --text-3: rgba(24, 24, 30, 0.56); --color-white-a04: rgba(0, 0, 0, 0.04); --color-white-a06: rgba(0, 0, 0, 0.05); --color-white-a08: rgba(0, 0, 0, 0.06); --color-white-a10: rgba(0, 0, 0, 0.08); --color-white-a12: rgba(0, 0, 0, 0.09); --color-white-a16: rgba(0, 0, 0, 0.12); --color-accent: #0a7fd1; --color-on-accent: #ffffff; --color-focus-ring: rgba(10, 127, 209, 0.8); --overlay-rgb: 24, 24, 30; --error-text: #c0283f; --warning-text: #9a6700; --info-text: #0a6db3; --popover-fill: rgba(252, 252, 254, 0.97); --mint-text: #1f8a5b; }
.settings-stage { --settings-card: #1b1d22; --settings-card-line: rgba(var(--overlay-rgb, 255, 255, 255), 0.07); height: 100%; color: var(--color-page-text); background: #131417; transition: background-color var(--motion-medium) var(--motion-ease), color var(--motion-medium) var(--motion-ease); }
.settings-stage--light { --settings-card: #ffffff; --settings-card-line: rgba(0, 0, 0, 0.08); background: #eceef2; }
.plugin-btn { height: 28px; padding: 0 11px; display: inline-flex; align-items: center; gap: 6px; color: var(--text-1); background: var(--color-white-a08); border: 1px solid var(--color-white-a08); border-radius: var(--radius-md); font: inherit; font-size: 12px; font-weight: 600; white-space: nowrap; cursor: pointer; transition: background-color var(--motion-fast) var(--motion-ease), border-color var(--motion-fast) var(--motion-ease), color var(--motion-fast) var(--motion-ease); }
.plugin-btn:hover:not(:disabled) { background: var(--color-white-a12, rgba(var(--overlay-rgb, 255, 255, 255), 0.12)); }
.plugin-btn:disabled { cursor: default; opacity: 0.5; }
.plugin-btn--sm { height: 26px; padding: 0 9px; font-size: 11.5px; }
.plugin-btn--ghost { background: transparent; border-color: transparent; color: var(--text-2); }
.plugin-btn--ghost:hover:not(:disabled) { color: var(--text-1); background: var(--color-white-a06); }
.plugin-btn--primary { color: var(--info-text, var(--color-accent)); border-color: color-mix(in srgb, var(--color-accent) 36%, transparent); background: color-mix(in srgb, var(--color-accent) 12%, transparent); }
.plugin-btn--primary:hover:not(:disabled) { background: color-mix(in srgb, var(--color-accent) 20%, transparent); }
.plugin-btn--danger { color: var(--error-text, #ff9aa9); border-color: transparent; background: transparent; }
.plugin-btn--danger:hover:not(:disabled) { background: color-mix(in srgb, var(--error-text, #ff9aa9) 12%, transparent); }
.plugin-btn--danger-solid { color: var(--error-text, #ff9aa9); border-color: color-mix(in srgb, var(--error-text, #ff9aa9) 40%, transparent); background: color-mix(in srgb, var(--error-text, #ff9aa9) 16%, transparent); }
.plugin-btn--danger-solid:hover:not(:disabled) { background: color-mix(in srgb, var(--error-text, #ff9aa9) 24%, transparent); }
.plugin-icon-btn { flex: none; width: 28px; height: 28px; display: inline-grid; place-items: center; padding: 0; color: var(--text-2); background: transparent; border: 1px solid transparent; border-radius: var(--radius-md); cursor: pointer; transition: background-color var(--motion-fast) var(--motion-ease), color var(--motion-fast) var(--motion-ease); }
.plugin-icon-btn:hover:not(:disabled) { color: var(--text-1); background: var(--color-white-a08); }
.plugin-icon-btn:disabled { cursor: default; opacity: 0.5; }
.plugin-icon-btn--outlined { border-color: var(--color-white-a10); background: var(--color-white-a06); }
.plugin-badge { flex: none; display: inline-flex; align-items: center; height: 18px; padding: 0 6px; border: 1px solid var(--color-white-a12); border-radius: 5px; color: var(--text-2); font-size: 11px; font-weight: 600; white-space: nowrap; }
.plugin-badge--official { color: var(--color-accent); border-color: color-mix(in srgb, var(--color-accent) 45%, transparent); }
.plugin-badge--warn { color: var(--warning-text, #ffd166); border-color: color-mix(in srgb, var(--warning-text, #ffd166) 45%, transparent); }
.plugin-badge--new { color: var(--mint-text, #7ee2b8); border-color: color-mix(in srgb, var(--mint-text, #7ee2b8) 45%, transparent); }
.plugin-verified { flex: none; display: inline-grid; place-items: center; width: 15px; height: 15px; color: var(--color-on-accent); background: var(--color-accent); border-radius: 50%; }
.plugin-icon { position: relative; flex: none; width: 40px; height: 40px; display: grid; place-items: center; color: var(--text-1); background: var(--color-white-a08); border: 1px solid var(--color-white-a08); border-radius: 10px; font-size: 16px; font-weight: 650; }
.plugin-icon--lg { width: 52px; height: 52px; border-radius: 13px; font-size: 21px; }
.plugin-icon--sm { width: 28px; height: 28px; border-radius: 7px; font-size: 12px; }
.plugin-icon--dim { color: var(--text-3); }
.plugin-icon--img { background: transparent; border-color: transparent; }
.plugin-icon__img { width: 100%; height: 100%; display: block; object-fit: contain; border-radius: inherit; user-select: none; }
.plugin-icon--dim .plugin-icon__img { opacity: 0.5; }
.plugin-icon__dot { position: absolute; right: -2px; bottom: -2px; width: 11px; height: 11px; border: 2px solid var(--settings-card, #1b1d22); border-radius: 50%; background: var(--text-3); }
.plugin-icon__dot--ok { background: var(--mint-text, #7ee2b8); }
.plugin-icon__dot--bad { background: var(--error-text, #ff9aa9); }
.plugin-icon__dot--wait { background: var(--warning-text, #ffd166); }
.plugin-callout { margin: 0; padding: 10px 12px; display: flex; gap: 10px; align-items: flex-start; color: var(--text-2); background: var(--color-white-a04); border: 1px solid var(--color-white-a08); border-radius: var(--radius-lg); font-size: 12.5px; line-height: 1.5; overflow-wrap: anywhere; }
.plugin-callout > svg { flex: none; margin-top: 2px; }
.plugin-callout b { color: var(--text-1); }
.plugin-callout--info > svg { color: var(--color-accent); }
.plugin-callout--warn { background: color-mix(in srgb, var(--warning-text, #ffd166) 8%, transparent); border-color: color-mix(in srgb, var(--warning-text, #ffd166) 35%, transparent); }
.plugin-callout--warn > svg { color: var(--warning-text, #ffd166); }
.plugin-callout--bad { background: color-mix(in srgb, var(--error-text, #ff9aa9) 8%, transparent); border-color: color-mix(in srgb, var(--error-text, #ff9aa9) 35%, transparent); }
.plugin-callout--bad > svg { color: var(--error-text, #ff9aa9); }
.plugin-page :is(.plugin-btn, .plugin-icon-btn, .plugin-link, .plugin-search__clear):focus-visible, .plugin-menu :is(.plugin-icon-btn):focus-visible { outline: 2px solid var(--color-focus-ring); outline-offset: 2px; }
.plugin-dialog__backdrop { position: fixed; inset: 0; z-index: 60; display: grid; place-items: center; padding: 24px; background: rgba(var(--overlay-rgb, 0, 0, 0), 0.52); backdrop-filter: blur(5px); }
.plugin-dialog { width: min(720px, 100%); max-height: min(86vh, 760px); display: flex; flex-direction: column; overflow: hidden; background: var(--popover-fill, var(--color-surface-dark)); border: 1px solid var(--color-white-a16); border-radius: 14px; box-shadow: 0 18px 48px rgba(var(--overlay-rgb, 0, 0, 0), 0.36); animation: plugin-dialog-in var(--motion-medium) var(--motion-ease-out) backwards; }
.plugin-dialog__head { flex: none; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 14px; padding: 18px 18px 12px; }
.plugin-dialog__heading { min-width: 0; display: grid; gap: 2px; }
.plugin-dialog__title { min-width: 0; color: var(--text-1); font-size: 17px; font-weight: 700; overflow-wrap: anywhere; }
.plugin-dialog__sub { overflow: hidden; color: var(--text-3); font-size: 12.5px; text-overflow: ellipsis; white-space: nowrap; }
.plugin-dialog__head-actions { display: flex; align-items: center; gap: 8px; }
.plugin-dialog__body { flex: 1; min-height: 0; overflow-y: auto; display: grid; align-content: start; gap: 14px; padding: 16px 18px; }
.plugin-dialog__desc { margin: 0; color: var(--text-2); font-size: 13px; line-height: 1.6; }
.plugin-dialog__foot { flex: none; display: flex; flex-wrap: wrap; align-items: center; gap: 8px; padding: 12px 18px; border-top: 1px solid var(--color-white-a08); }
.plugin-dialog__grow { flex: 1; }
.plugin-dialog__confirm { flex: 1; }
.plugin-dialog__error { margin: 6px 0 0; color: var(--error-text, #ff9aa9); }
.plugin-tabs { flex: none; display: flex; gap: 2px; padding: 0 18px; overflow-x: auto; border-bottom: 1px solid var(--color-white-a06); scrollbar-width: none; }
.plugin-tabs__tab { position: relative; flex: none; padding: 8px 10px 10px; color: var(--text-3); background: transparent; border: 0; border-radius: 6px 6px 0 0; font: inherit; font-size: 13px; white-space: nowrap; cursor: pointer; transition: color var(--motion-fast) var(--motion-ease), background-color var(--motion-fast) var(--motion-ease); }
.plugin-tabs__tab:hover { color: var(--text-1); background: var(--color-white-a04); }
.plugin-tabs__tab[aria-selected="true"] { color: var(--text-1); font-weight: 600; }
.plugin-tabs__tab[aria-selected="true"]::after { content: ""; position: absolute; right: 10px; bottom: -1px; left: 10px; height: 2px; background: var(--color-accent); border-radius: 2px; }
.plugin-tabs__tab:focus-visible { outline: 2px solid var(--color-focus-ring); outline-offset: -2px; }
.plugin-dialog .plugins-v3__rules-group { padding-top: 0; border-top: 0; }
@media (max-width: 560px) { .plugin-dialog__backdrop { padding: 12px; } .plugin-dialog__head { grid-template-columns: auto minmax(0, 1fr); } .plugin-dialog__head-actions { grid-column: 1 / -1; justify-content: flex-end; margin-top: -6px; } }
@media (prefers-reduced-motion: reduce) { .plugin-dialog { animation: none; } }
.market-card { min-width: 0; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; gap: 8px; padding: 12px 14px; overflow: hidden; container: market-card / inline-size; background: var(--color-white-a04); border: 1px solid var(--color-white-a06); border-radius: var(--radius-xl); cursor: pointer; transition: background-color var(--motion-fast) var(--motion-ease), border-color var(--motion-fast) var(--motion-ease); }
.market-card:hover { background: var(--color-white-a06); border-color: var(--color-white-a10); }
.market-card--skeleton { grid-template-rows: auto auto 1fr auto; cursor: default; }
.market-card__main { min-width: 0; display: grid; align-content: start; gap: 8px; }
.market-cover { position: relative; height: 104px; margin: -12px -14px 2px; display: grid; place-items: center; overflow: hidden; background: color-mix(in srgb, var(--market-tint, transparent) 22%, var(--color-white-a04)); border-bottom: 1px solid var(--color-white-a06); }
.market-cover__shot { position: absolute; left: 14px; top: 14px; width: calc(100% - 28px); display: block; border-radius: 9px 9px 0 0; outline: 1px solid var(--color-white-a10); box-shadow: 0 6px 18px var(--market-cover-shadow, rgba(0, 0, 0, 0.28)); user-select: none; }
.market-cover__shot:not([src]) { visibility: hidden; }
.market-cover__shot--strip { top: 50%; border-radius: 9px; transform: translateY(-50%); }
.market-cover__count { position: absolute; right: 8px; bottom: 7px; padding: 0 6px; color: var(--market-scrim-text, #fff); background: rgba(var(--overlay-rgb, 0, 0, 0), 0.62); border-radius: 999px; font-size: 10px; line-height: 16px; white-space: nowrap; }
.market-card--skeleton:hover { background: var(--color-white-a04); border-color: var(--color-white-a06); }
.market-card__head { min-width: 0; display: flex; align-items: center; gap: 10px; }
.market-card__title { min-width: 0; flex: 1; display: grid; gap: 1px; }
.market-card__line { min-width: 0; display: flex; align-items: center; gap: 6px; }
.market-card__name { min-width: 0; padding: 0; overflow: hidden; color: var(--text-1); background: transparent; border: 0; font: inherit; font-size: 13.5px; font-weight: 650; text-align: left; text-overflow: ellipsis; white-space: nowrap; cursor: pointer; }
.market-card__sub { overflow: hidden; color: var(--text-3); font-size: 12px; text-overflow: ellipsis; white-space: nowrap; }
.market-card__desc { display: -webkit-box; margin: 0; overflow: hidden; color: var(--text-2); font-size: 12.5px; line-height: 1.5; -webkit-box-orient: vertical; -webkit-line-clamp: 2; line-clamp: 2; }
.market-card__foot { grid-column: 1 / -1; min-width: 0; display: flex; align-items: center; justify-content: space-between; gap: 8px; padding-top: 8px; border-top: 1px solid var(--color-white-a06); }
.market-card__facts { min-width: 0; overflow: hidden; color: var(--text-3); font-size: 12px; text-overflow: ellipsis; white-space: nowrap; }
.market-card__warn { color: var(--warning-text, #ffd166); }
.market-card__action { flex: none; display: inline-flex; align-items: center; gap: 6px; }
.market-card__installed { display: inline-flex; align-items: center; gap: 4px; color: var(--mint-text, #7ee2b8); font-size: 12px; font-weight: 600; white-space: nowrap; }
.market-card__island { gap: 4px; }
.market-card__blocked { color: var(--text-3); font-size: 12px; white-space: nowrap; }
.market-card__blocked--bad { color: var(--error-text, #ff9aa9); }
.market-badge--bad { color: var(--error-text, #ff9aa9); border-color: color-mix(in srgb, var(--error-text, #ff9aa9) 45%, transparent); }
.market-badge--ok { color: var(--mint-text, #7ee2b8); border-color: color-mix(in srgb, var(--mint-text, #7ee2b8) 45%, transparent); }
.market-dialog { container-type: inline-size; }
.market-dialog .plugin-dialog__body { grid-auto-rows: max-content; }
.market-dialog--wide { width: min(860px, 100%); }
.market-dialog--small { width: min(540px, 100%); }
.market-dialog__title { white-space: normal; }
.market-mono { font-family: var(--font-mono, Consolas, "Cascadia Mono", monospace); }
.market-shots { display: flex; gap: 10px; overflow-x: auto; padding-bottom: 2px; scrollbar-width: thin; }
.market-shot { flex: none; width: 220px; margin: 0; display: grid; gap: 6px; }
.market-shot__open { display: block; padding: 0; background: transparent; border: 0; border-radius: var(--radius-lg); cursor: zoom-in; }
.market-shot img { display: block; width: 100%; aspect-ratio: 16 / 10; object-fit: contain; background: var(--color-white-a06); border: 1px solid var(--color-white-a08); border-radius: var(--radius-lg); }
.market-shot figcaption { overflow: hidden; color: var(--text-3); font-size: 12px; text-overflow: ellipsis; white-space: nowrap; }
.market-detail { min-width: 0; display: grid; grid-template-columns: minmax(0, 1fr) 210px; align-items: start; gap: 18px; }
.market-detail__main { min-width: 0; display: grid; gap: 12px; }
.market-detail__tabs { padding: 0; }
.market-detail__panel { min-width: 0; display: grid; gap: 10px; }
.market-detail__aside { min-width: 0; display: grid; gap: 12px; padding: 12px 14px; background: var(--color-white-a04); border: 1px solid var(--color-white-a06); border-radius: var(--radius-xl); }
.market-detail__aside dl { margin: 0; display: grid; gap: 8px; }
.market-detail__aside dt { color: var(--text-3); font-size: 11.5px; }
.market-detail__aside dd { margin: 1px 0 0; color: var(--text-1); font-size: 12.5px; overflow-wrap: anywhere; }
.market-detail__links { display: grid; justify-items: start; gap: 2px; padding-top: 10px; border-top: 1px solid var(--color-white-a06); }
.market-detail__links .plugin-btn { padding: 0 6px; margin-left: -6px; }
.market-markdown { padding: 12px 14px; background: var(--color-white-a04); border: 1px solid var(--color-white-a06); border-radius: var(--radius-lg); }
.market-page :is(.market-card__name, .plugin-chip, .market-owned__toggle):focus-visible, .market-viewer__btn:focus-visible, .market-dialog :is(.plugin-btn, .plugin-icon-btn, .market-card__name, .market-shot__open):focus-visible { outline: 2px solid var(--color-focus-ring); outline-offset: 2px; }
.settings-stage--light :is(.market-card, .market-detail__aside, .market-markdown, .market-owned__toggle) { background: var(--settings-card, var(--color-white)); border-color: var(--settings-card-line, var(--color-white-a08)); }
.settings-stage--light :is(.market-card, .market-owned__toggle):hover { border-color: var(--color-white-a16); }
.settings-stage--light .market-cover { background: color-mix(in srgb, var(--market-tint, transparent) 14%, var(--color-white-a04)); }
@container market-card (max-width: 340px) { .market-card__island-label { display: none; } }
@container (max-width: 620px) { .market-detail { grid-template-columns: minmax(0, 1fr); } }
@container (max-width: 520px) { .market-shot { width: 180px; } .market-dialog .plugin-dialog__head .market-card__line { flex-wrap: wrap; } }
.markdown { min-width: 0; color: var(--text-2); font-size: 12px; line-height: 1.6; overflow-wrap: anywhere; }
.markdown > :first-child { margin-top: 0; }
.markdown > :last-child { margin-bottom: 0; }
.markdown h3, .markdown h4, .markdown h5, .markdown h6 { margin: 12px 0 4px; color: var(--color-text); font-weight: 600; line-height: 1.35; }
.markdown h3 { font-size: 14px; }
.markdown h4 { font-size: 13px; }
.markdown h5, .markdown h6 { font-size: 12px; }
.markdown p, .markdown ul, .markdown ol, .markdown blockquote, .markdown pre { margin: 6px 0; }
.markdown ul, .markdown ol { padding-left: 18px; }
.markdown blockquote { padding-left: 10px; color: var(--text-2); border-left: 2px solid var(--color-white-a16); }
.markdown code { padding: 1px 4px; font-family: Consolas, "Cascadia Mono", monospace; font-size: 11px; background: var(--color-white-a08); border-radius: var(--radius-sm); }
.markdown pre { padding: 8px 10px; overflow-x: auto; background: var(--color-white-a08); border-radius: var(--radius-md); }
.markdown pre code { padding: 0; background: transparent; white-space: pre; }
.markdown hr { margin: 10px 0; border: 0; border-top: 1px solid var(--color-white-a10); }
.markdown a { color: var(--info-text, #8fd8ff); text-decoration: underline; text-underline-offset: 2px; cursor: pointer; }
.markdown a:focus-visible { outline: 2px solid var(--color-focus-ring); outline-offset: 1px; }
